import java.util.*;
class CompositeIndex {record Result(List<String>prefix,boolean covered,int heapFetches,List<Map<String,Integer>>output){}
static int compare(Map<String,Integer>row,List<String>prefix,Map<String,Integer>filters){for(String col:prefix){int d=Integer.compare(row.get(col),filters.get(col));if(d!=0)return d;}return 0;}
static Result query(List<Map<String,Integer>>rows,List<String>columns,Map<String,Integer>filters,List<String>projection){List<Map<String,Integer>>sorted=new ArrayList<>(rows);sorted.sort((a,b)->{for(String col:columns){int d=Integer.compare(a.get(col),b.get(col));if(d!=0)return d;}return Integer.compare(a.get("id"),b.get("id"));});List<String>prefix=new ArrayList<>();for(String col:columns){if(!filters.containsKey(col))break;prefix.add(col);}boolean covered=columns.containsAll(projection)&&columns.containsAll(filters.keySet());int lo=0,hi=sorted.size();while(lo<hi){int mid=(lo+hi)/2;if(compare(sorted.get(mid),prefix,filters)<0)lo=mid+1;else hi=mid;}int start=lo;hi=sorted.size();while(lo<hi){int mid=(lo+hi)/2;if(compare(sorted.get(mid),prefix,filters)<=0)lo=mid+1;else hi=mid;}
List<Map<String,Integer>>out=new ArrayList<>();for(int i=start;i<lo;i++){var row=sorted.get(i);if(filters.entrySet().stream().allMatch(e->Objects.equals(row.get(e.getKey()),e.getValue()))){Map<String,Integer>projected=new LinkedHashMap<>();for(String col:projection)projected.put(col,row.get(col));out.add(projected);}}return new Result(prefix,covered,covered?0:lo-start,out);}
static String estimate(int n,double percent,boolean prefix,boolean covered){double candidates=prefix?n*percent/100:n,seek=prefix?Math.ceil(Math.log(Math.ceil(n/4.0)+1)/Math.log(2)):0,index=seek+Math.ceil(candidates/4)+(covered?0:2*candidates),scan=Math.ceil(n/4.0);return index<scan?"index":"sequential";}}
// Cost units are assumptions, not real provider latency or PostgreSQL statistics.
